create extension if not exists pgcrypto;
create table public.floors(id text primary key,owner_id uuid not null default auth.uid() references auth.users(id),name text not null,address text not null default '',photo_uri text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.rooms(id text primary key,owner_id uuid not null default auth.uid() references auth.users(id),floor_id text not null references public.floors(id) on delete cascade,room_number text not null,monthly_rent numeric not null default 0,status text not null check(status in('vacant','occupied')),photo_uri text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.tenants(id text primary key,owner_id uuid not null default auth.uid() references auth.users(id),room_id text not null references public.rooms(id),full_name text not null,phone text not null,email text,id_type text not null,id_number text not null,move_in_date date not null,monthly_rent numeric not null,photo_uri text,notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.documents(id text primary key,owner_id uuid not null default auth.uid() references auth.users(id),tenant_id text not null references public.tenants(id) on delete cascade,document_type text not null,local_uri text,remote_path text,file_name text not null,mime_type text,created_at timestamptz not null default now());
create table public.bills(id text primary key,owner_id uuid not null default auth.uid() references auth.users(id),tenant_id text not null references public.tenants(id),bill_month text not null,rent numeric not null,electricity numeric not null default 0,water numeric not null default 0,waste numeric not null default 0,additional numeric not null default 0,previous_due numeric not null default 0,advance_used numeric not null default 0,paid_amount numeric not null default 0,total numeric not null,balance numeric not null,status text not null check(status in('paid','partial','due')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(tenant_id,bill_month));
alter table public.floors enable row level security;alter table public.rooms enable row level security;alter table public.tenants enable row level security;alter table public.documents enable row level security;alter table public.bills enable row level security;
do $$ declare t text; begin foreach t in array array['floors','rooms','tenants','documents','bills'] loop execute format('create policy "Owner controls own %1$s" on public.%1$I for all to authenticated using (owner_id=auth.uid()) with check (owner_id=auth.uid())',t); end loop; end $$;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('tenant-private','tenant-private',false,10485760,array['image/jpeg','image/png','application/pdf']) on conflict(id) do nothing;
create policy "Owner uploads private files" on storage.objects for insert to authenticated with check(bucket_id='tenant-private' and (storage.foldername(name))[1]=auth.uid()::text);
create policy "Owner reads private files" on storage.objects for select to authenticated using(bucket_id='tenant-private' and (storage.foldername(name))[1]=auth.uid()::text);
create policy "Owner updates private files" on storage.objects for update to authenticated using(bucket_id='tenant-private' and (storage.foldername(name))[1]=auth.uid()::text);
create policy "Owner deletes private files" on storage.objects for delete to authenticated using(bucket_id='tenant-private' and (storage.foldername(name))[1]=auth.uid()::text);
